"""Review selected relative, source, complement and restriction constructions in 3–5."""
import argparse
from semantic_review import ReviewBatch, validate


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    b = ReviewBatch("semantic-review-004", "Individually selected flagged constructions in surahs 3–5, retaining valid idioms and correcting source-role loss. Unselected difficult clauses remain pending.")
    if b.exists:
        validate()
        return
    def p(ayah, identifier, pieces, reason):
        b.phrase(ayah + "-" + identifier, [(text, f"{ayah}:{word}" if word else None) for text, word in pieces], reason)
    def c(ayah, identifier, values, reason):
        b.change(ayah + "-" + identifier, {f"{ayah}:{word}": value for word, value in values.items()}, reason)
    def d(keys, reason, retained=False):
        for key in keys.split():
            b.decide(key, reason, retained)
    p("3:7", "relative-revealer", [("indir", 3), ("en", 2), ("dir", 0)], "Alladhi is an overt relative pronoun in a nominal predicate: indiren. The Turkish relative construction can describe the completed revelation without retaining a finite indirdi at both positions.")
    p("3:7", "those-with-deviation", [("kalpleri", 17), ("nde", 16), (" ", 0), ("eğrilik", 18), (" bulun", 0), ("anlar", 15)], "Alladhina supplies the nominal relative persons; fi qulubihim supplies in their hearts and zaygh supplies deviation. Turkish kalplerinde eğrilik bulunanlar exposes each contribution, with bulun as shared support for the Arabic nominal clause.")
    c("3:7", "topic-contrast", {14: "ise"}, "Fa-amma supplies topic contrast; Turkish ise does not need to repeat the following lexical deviation phrase.")
    d("3:7:2 3:7:15", "Restore the two overt relative functions: the revealer and the people whose hearts contain deviation. No decision is made here about the disputed stopping point later in this ayah.")
    c("3:22", "relative-predicate", {1: "işte onlar", 2: "öyle kimselerdir ki"}, "Ulaika is a demonstrative, not thus; alladhina explicitly introduces the people whose works have become worthless.")
    d("3:22:2", "Restore the demonstrative and nominal relative predicate without repeating the finite boşa çıkmıştır as context-only.")
    for ayah, minword, nounword, noun, ending, changes in [
        ("3:15", 20, 21, "Allah", "'tan", {19: "ve bir rıza"}),
        ("3:112", 16, 17, "Allah", "'tan", {15: "bir gazaba"}),
        ("3:157", 9, 10, "Allah", "'tan", {8: "elbette bir bağışlanma", 11: "ve rahmet"}),
        ("3:159", 3, 4, "Allah", "'tan", {2: "bir rahmet"}),
        ("3:171", 3, 4, "Allah", "'tan", {1: "sevinirler", 2: "bir nimetle", 5: "ve lütufla"}),
    ]:
        reason = "Min marks the source of the named favor, approval, anger or mercy. Restore the natural Allah'tan construction and keep its associated noun unpossessed; do not duplicate both a genitive and an ablative."
        p(ayah, "source", [(noun, nounword), (ending, minword)], reason)
        c(ayah, "source-noun", changes, reason + (" Yastabshiruna describes receiving gladness, not announcing good news to an unspecified other party." if ayah == "3:171" else ""))
        d(f"{ayah}:{minword}", reason)
    for minword, nounword, stem, ending in [(9, 10, "Allah", "'ın"), (12, 13, "insanlar", "ın")]:
        p("3:112", "covenant-origin-" + str(minword), [(stem, nounword), (ending, minword)], "In the covenant/rope idiom, Turkish naturally expresses the originating party with a genitive: Allah'ın / insanların ahdi. Expose that functional relation. Remove the unrequired restriction [inanan] from the general Arabic al-nas.")
        d(f"3:112:{minword}", "Retain the inherited covenant reading of habl, with source min expressed functionally by a Turkish genitive, not a universal equivalence of min and possession.")
    p("3:112", "past-habit", [("inkar ediyor", 24), ("lardı", 23)], "Kanu yakfuruna has past habitual scope. Restore -lardı rather than a context-only copy of the present inkar ediyorlar.")
    d("3:112:23", "Make past habitual predication explicit in inkar ediyorlardı, consistently with the following past killing clause.")
    p("3:117", "worldly-life", [("bu ", 5), ("dünya ", 7), ("hayatı", 6), ("nda", 4)], "Fi hadhihi al-hayati al-dunya is in this worldly life. Put life at al-hayat, worldly at al-dunya and the locative at fi instead of displacing each counterpart.")
    d("3:117:4", "Expose the locative on hayatında and restore each noun/adjective to its Arabic location.")
    p("3:126", "victory-source", [("katı", 14), ("ndan", 13)], "Min indi Allahi identifies the source of help, not merely its presence at a place. Restore katından with min owning the ablative.")
    d("3:126:13", "Restore the source relation in katından; the following Allah entry supplies the possessor.")
    d("3:28:6 3:79:16 4:139:5 4:144:8", "Min duni is rendered idiomatically as bırakıp with the preceding/following accusative object. The replacement/exclusion relation is expressed by the whole construction; an extra ablative would conflict with this Turkish verbal frame.", True)
    d("3:50:5 3:81:8 5:44:18", "This min identifies the preceding scriptural content or its kind. The Turkish object phrase already supplies that content; retain its explanatory relation without forcing a spatial/source ablative.", True)
    d("3:125:6", "Min fawrihim hadha describes the immediate rush/occasion, naturally ansızın / şu anda in the supplied wording. No independent suffix is required at min; retain the context view rather than inventing an origin phrase.", True)
    d("3:134:9", "Afa an takes the forgiven people as a Turkish direct object: insanları affetmek. The Arabic preposition is absorbed by the Turkish verb's valency; do not force insanlardan affetmek.", True)
    p("3:145", "negative-possibility", [("ve ", 1), ("mümkün", 2), (" değil", 1), ("dir", 2)], "Ma kana li-nafsin an tamuta denies the possibility of death apart from divine permission. Turkish mümkün değildir expresses this construction; possible is a contextual modal reading of the whole ma-kana-li frame, not a dictionary gloss of kana alone.")
    d("3:145:2", "Restore the modal/couplar function in the negative-possibility construction rather than copying hiçbir kişi için.")
    c("3:146", "quantified-prophet", {2: "(bir peygamber)", 3: "bir peygamber", 5: "onunla beraber"}, "Ka-ayyin min nabiyyin is a many-a-prophet quantifier, not from a prophet. Remove the false ablative; maahu contains a singular pronoun referring to the prophet.")
    d("3:146:2 3:146:3", "Restore the uninflected quantified noun and singular with-him pronoun. This follows the supplied Hafs Arabic qatala; variant readings are not substituted.")
    p("3:147", "negative-past", [("ve ", 1), ("değil", 1), ("di", 2)], "Wa-ma kana ... illa is a negative past copula plus exception; expose past -di at kana and negation at ma.")
    d("3:147:2", "Expose the past copula while retaining the exception and nominal saying construction.")
    p("3:156", "campaign-state", [("savaşta", 16), (" ", 0), ("oldukları", 15)], "Kanu ghuzzan describes being on a military expedition under the shared when clause. Express nominal campaign state at ghuzzan and its relative copula at kanu.")
    d("3:156:15", "Restore the copular contribution without converting the reported counterfactual that follows into a factual death claim.")
    p("3:160", "demonstrative", [("o", 10), (" ", 0), ("kimse", 11)], "Dha is overt demonstrative material in the rhetorical who-is-that-who question; expose o separately from the person-relative phrase.")
    d("3:160:10", "Restore the interrogative demonstrative rather than a context-only copy of kimse.")
    p("3:172", "after-injury", [("kendilerine isabet et", 8), ("tik", 7), ("ten", 5), (" sonra bile", 6)], "Min badi ma asabahumu al-qarhu is after injury befell them. Expose the nominalizing relative -tik, ablative -ten and after relation rather than the inherited disconnected ne ki / isabet etti.")
    d("3:172:5", "Make the complete after-being-injured construction visible; bile preserves the inherited concessive emphasis of the clause.")
    p("3:178", "restriction", [("biz ", 11), ("yalnızca ", 10), ("süre veriyoruz", 11)], "Innama is an overt restrictive particle. Restore yalnızca rather than copying the whole predicate as context-only.")
    d("3:178:10", "Restore the restrictive particle at its own location; the following purpose clause states the restricted purpose.")
    d("3:189:6 3:189:7 3:189:8 5:17:39 5:17:40 5:17:41", "Retain the individually inspected ability construction: her şeye kadirdir uses a dative, whereas her şeyi yapabilendir uses an accusative. The displays correctly expose ala, kull and shay according to their Turkish frame; no global replacement of the case is justified.", True)
    c("3:193", "quoted-command", {7: "[diye]", 8: "inanın", 16: "bizden"}, "An introduces the caller's quoted command, naturally inanın diye; mark the introducer as explanatory. Anna in the later expiation request explicitly refers to us, not to the following noun our misdeeds.")
    d("3:193:7 3:193:16", "Separate the quoted-command introducer from the imperative and restore the first-person plural complement in the expiation request.")
    d("3:195:10 4:8:4 4:36:14", "Retain the natural Turkish classification/kinship phrase. Min dhakarin identifies sex rather than physical origin; ulu/dhi al-qurba is the lexical kinship expression akrabalar/yakın. No standalone Turkish sahip noun or artificial case ending is required.", True)
    p("4:6", "until-reaching", [("var", 5), ("ınca", 4), ("ya", 5)], "Hatta idha balaghu is until they reach the relevant age. Turkish varıncaya kadar incorporates the when contribution in -ınca and the endpoint construction in -ya kadar.")
    d("4:6:4", "Expose idha's temporal subordinate function in varıncaya kadar without inventing a separate time noun.")
    c("4:9", "relative-and-imperative", {1: "ve çekinsinler", 2: "[o] kimseler", 9: "kaygı duyacak olanlar"}, "Wa-l-yakhsha is a command and alladhina identifies those commanded. Khafu describes their hypothetical concern for weak descendants. The inherited kaygı duyanlar / çekinsinler had these functions reversed.")
    d("4:9:2", "Restore the relative persons and the actual command at the beginning; the following law clause remains hypothetical.")
    for ayah, neg, copula, tail in [("4:11", 35, 36, " da"), ("4:12", 7, 8, "sa"), ("4:12", 31, 32, "sa"), ("4:176", 22, 23, "sa [kız kardeşinin]")]:
        p(ayah, "absence-" + str(copula), [("mevcut", copula), (" ", 0), ("değil", neg), (tail, 0)], "Lam yakun expresses not being/existing in the inherited conditional. Expose mevcut and negation separately. The conditional ending and supplied antecedent are shared context; they are not lexical meanings falsely assigned to yakun.")
        d(f"{ayah}:{copula}", "Restore the existence predicate independently of negation; retain the inherited condition and the following child/possession phrase.")
    p("4:12", "positive-existence", [("mevcut", 12), ("sa", 0)], "Kana lahunna waladun in this condition asserts existence of children. Expose that predicate instead of copying the full pronoun/condition phrase.")
    c("4:12", "possession-only", {13: "onların"}, "Lahunna supplies possession; the conditional existence is now displayed at kana, so do not duplicate varsa as lexical possession.")
    d("4:12:12", "Expose positive existence and retain possession at lahunna, without changing any inheritance share.")
    c("4:11", "will-pronoun", {53: "ona [vasiyete] dair"}, "Biha refers to the will being made; it is not the following aw, which means or. Restore the pronoun and mark the antecedent as explanatory.")
    d("4:11:53", "Correct the displaced conjunction copied into the feminine pronominal preposition.")
    d("4:12:43 4:12:44 4:12:45 4:153:26 4:153:27 4:153:28 4:153:29", "Retain the inspected after construction: the ablative, sonra and content/relative contributions are separately visible and refer to the relevant will or arrival of proofs. No new source meaning or second time relation is introduced.", True)
    d("4:24:34", "Retain bihi as onun üzerinde in the mutual-agreement construction; it refers to the matter agreed upon. The following min badi separately supplies the after relation.", True)
    for ayah, qad, salaf in [("4:22", 10, 11), ("4:23", 48, 49)]:
        p(ayah, "completed-earlier", [("geçip git", salaf), ("miş", qad)], "Qad salafa denotes what has already passed. Expose completion with -miş and the passing predicate with geçip git instead of reducing both to the adverb geçmişte.")
        d(f"{ayah}:{qad}", "Restore the completed predicate in the exception about what has already passed.")
    p("4:23", "nursing-relation", [("süt", 17), (" [yoluyla]", 16)], "Min al-radaa describes the nursing relationship. Turkish süt is the established compound qualifier; [yoluyla] makes the relational source explicit without pretending it is a pronounced suffix in süt kardeşler.")
    d("4:23:16", "Keep the kinship meaning, exposing the nursing relation with a bracketed explanation instead of a nonexistent suffix.")
    c("4:23", "with-them", {28: "onlarla", 39: "[o] kimseler ki"}, "Bihinna refers to the wives with whom consummation occurred, not the following conditional eğer. Alladhina later qualifies the sons from one's own loins and is not just a context copy of sulbünüzden.")
    d("4:23:28 4:23:39", "Restore the feminine plural complement and the relative qualifier without changing the prohibited-kin categories.")
    p("4:24", "beyond-relative", [("ötesi", 14), ("nde olanlar", 13)], "Ma wara dhalikum identifies those beyond the enumerated prohibitions. Restore a nominal relative expression rather than displaying ma as an empty copy of ötesi.")
    d("4:24:13", "Expose the relative nominal content of ma; this is a local linguistic decision, not a new legal conclusion.")
    d("4:36:30 4:107:12 4:134:2", "Retain the Turkish nominal/relative predicate read in context: the kana support is absorbed in the characterization or conditional-relative istemek construction. Do not impose a completed past tense on a general description. These remain functional zero views with this explicit rationale.", True)
    d("4:46:18", "Ta'nan fi al-din is naturally dini taşlamak in the inherited Turkish verbal paraphrase. Fi is absorbed by the direct-object valency, not a locative suffix on religion.", True)
    d("4:47:11 4:47:13", "The scope of before extends over effacing faces and turning them or cursing: silip is a Turkish converb and döndürmemizden / lanetlememizden provide nominal complements. Retain the shared, nonlocal nominal scope rather than assigning a false local negative or an extra ending to silip.", True)
    c("4:47", "command-execution", {25: "ve [daima]", 28: "yerine getirilir"}, "Wa-kana introduces the general settled execution of the divine command. The bracketed daima explains its general scope, not an independent lexical word. Maf'ulan is executed, naturally yerine getirilir.")
    d("4:47:25", "Restore the conjunction and explain the general predication; the command is not the lexical meaning of kana.")
    d("4:49:3", "Alam tara ila is idiomatically görmedin mi with an accusative person-relative object. Ila does not require a literal toward phrase in this Turkish perception construction.", True)
    c("4:66", "quoted-command", {5: "[şöyle:]"}, "An introduces the content of the prescribed imperative, here kill; mark it as an explanatory content introducer rather than an unexplained duplicate command.")
    d("4:66:5", "Expose the quoted-command function of an without replacing the imperative with a third-person nominal.")
    c("4:72", "causal-temporal", {13: "[çünkü]"}, "Idh introduces the circumstance offered as the reason for the claimed favor: not being present with them. [Çünkü] makes this contextual connection visible; it is not a separate assertion about the divine approval of the speaker.")
    d("4:72:13", "Make the causal/circumstantial connection visible without duplicating the negative presence predicate.")
    d("4:73:9", "Retain the fused absence predicate yokmuş gibi under ka-an. The evidential/as-if construction expresses the counterfactual appearance; do not insert a factual positive existence or duplicate its predicate.", True)
    d("4:84:3 4:84:4", "Retain the individually inspected Allah'ın yolu / Allah'ın yolu complement views: noun and genitive possessor contributions remain foregrounded at sabil and Allah, with fi separately providing yolunda.", True)
    p("4:84", "hoped-complement", [("kır", 14), ("ma", 13), ("sı", 14)], "An yakuffa under asa is a hoped-for nominal complement. Restore kırması instead of a context-only copy of a finite kırar; the modal hope remains at asa.")
    d("4:84:13", "Expose an as nominalization in the hoped-for restraining of force.")
    d("4:92:2", "Ma kana li-muminin an yaqtula denies permissibility for a believer, not a historical inability to kill. The inherited yoktur plus a nominal killing complement conveys that prohibition; retain the copular support as functional zero rather than adding an erroneous past tense.", True)
    c("4:97", "relative-deceased", {2: "[o] kimseler ki"}, "Alladhina introduces the people whose souls the angels take while wronging themselves. Restore the person-relative expression instead of a context-only copy of canlarını alırken.")
    d("4:97:2", "Restore overt relative reference, preserving the condition of wronging themselves and the angels as agents.")
    p("4:98", "among-men", [("erkekler", 4), ("den", 3)], "Min al-rijali classifies the exempted oppressed people as among men, women and children. Expose the partitive ending on the first class; the coordinate categories share its relation.")
    d("4:98:3", "Make the class/partitive relation explicit; the coordinated women and children are retained separately.")
    p("4:99", "pardon-complement", [("affet", 5), ("me", 4), ("si", 5)], "An yafuwa is a nominal complement under asa. Expose the nominalizer rather than copying the entire affetmesi.")
    d("4:99:4", "Restore the complement function while leaving the hope/possibility at asa.")
    p("4:101", "enemy-predication", [("düşmanınız", 22), ("dır", 20)], "Kanu supplies predication of the disbelievers as enemies in this general statement, not an independent possessive sizin.")
    d("4:101:20", "Expose the nominal copula on düşmanınızdır; lakum retains the beneficiary/adversative pronoun relation.")
    d("4:102:16 4:102:44 4:103:16", "Retain the inspected Turkish construction: min waraikum is arkanıza under the motion paraphrase geçsinler; kana bikum adhan is zahmet çekerseniz in the conditional; kanat ... kitaban is absorbed in farz kılınmıştır. No literal physical-from phrase or ceased past obligation is introduced.", True)
    d("4:108:15", "Min al-qawl identifies the disapproved utterance after the relative verbal phrase. The direct-object sözü naturally carries this explanatory/content relation without an extra ablative.", True)
    c("4:108", "general-circumscription", {17: "ve [daima]"}, "Wa-kana supplies conjunction and settled general predication in the surrounding-awareness clause. Bracketed daima is explanatory; the completed Turkish kuşatmıştır predicate is retained.")
    d("4:108:17", "Restore the missing conjunction and identify the general copular support without making Allah its lexical meaning.")
    d("4:119:15", "Min duni Allahi is idiomatically Allah'ın yerine in this inherited frame. The substitution relation is already explicit in yerine; no second ablative is necessary.", True)
    d("4:124:3", "Min al-salihat is a partitive/classification of righteous acts. Turkish güzel işler yaparsa naturally leaves the class uninflected; do not add a source ablative or claim that no acts are required.", True)
    c("4:126", "general-encompassing", {8: "ve [daima]"}, "Wa-kana is conjunction plus general predication, absorbed in the inherited encompassing predicate; it does not mean the following Allah noun.")
    d("4:126:8", "Restore conjunction and explain general predicate support without adding a ceased past state.")
    p("4:129", "justice-infinitive", [("[tam] adaletli davran", 4), ("ma", 3), ("ya", 4)], "An tadilu is a verbal complement of ability, not a bare noun adalet. Restore the action and nominalizer in adaletli davranmaya; keep inherited [tam] as explanatory scope.")
    c("4:129", "ability-predicate", {1: "ve asla (güç yetire)me(yeceksiniz)", 2: "(ve asla) güç yetire(me)yeceksiniz"}, "Lan negates future ability; tastatiu is ability itself. Distinguish güç yetirmek from the following justice action rather than placing all action in yapamazsınız.")
    d("4:129:3", "Restore the verbal complement of ability, retaining the ensuing prohibition on total inclination.")
    c("4:130", "abundance-predication", {8: "ve [daima]", 9: "Allah'ın", 10: "[lütfu] geniştir"}, "Retain the supplied contextual abundance reading of wasi with explanatory lütfu, but write the intended genitive properly and restore wa-kana's conjunction/general predication. Allah[ın] is not an intelligible source-role display.")
    d("4:130:8", "Keep the contextual abundance paraphrase, clearly mark its supplied noun, and restore conjunction; do not assert this exhausts the divine name's meanings.")
    p("4:135", "do-not-follow-desire", [("öyle ise ", 23), ("keyfinize", 25), (" ", 0), ("uy", 24), ("ma", 23), ("yın", 24)], "Fa-la tattabiu al-hawa directly prohibits following desire. Restore its actual imperative-negation structure instead of subordinating uymak to an independently negated sapmak.")
    p("4:135", "lest-deviate", [("adaletten sap", 27), ("ma", 26), ("manız için", 26)], "An tadilu is read here in the deviation/lest sense used by the English reference and inherited Turkish meaning. Express the preventive complement as adaletten sapmamanız için; this is an interpretive choice within the attested justice/deviation analyses.")
    d("4:135:23 4:135:24 4:135:25 4:135:26 4:135:27", "Restore the prohibition on following desire and its separate preventive complement. The selected deviation analysis is recorded rather than treated as the only possible lexical analysis of adala.")
    d("5:2:33", "Retain the source relation distributed over Mescid-i Haram'dan: the case ending is on the final member of the proper-name phrase, so min's context view at Mescid-i is not a missing religious-location meaning.", True)
    p("5:8", "not-doing-justice", [("adil davran", 15), ("ma", 14), ("ma", 14), ("ya", 13)], "Alla tadilu is a negative justice complement, adil davranmamaya, under the incitement verb. Expose both negation and nominalization at alla and the governed dative at ala, instead of a context-only adaletten.")
    c("5:8", "incitement", {9: "ve (sizi sevk et)me(sin)", 10: "(ve) sizi sevk et(me)sin"}, "Wa-la yajrimannakum ... ala forbids hatred from inciting injustice. The Turkish sevk etmek frame governs the dative nominal action; ala supplies that dative rather than an unrelated topluluğa karşı phrase.")
    d("5:8:14", "Restore negative nominalized justice and its incitement frame. This is the instruction not to let hatred produce injustice, not a prohibition on justice.")
    p("5:29", "burden-complement", [("senin yüklen", 4), ("me", 3), ("ni", 4)], "An tabua is the content of I wish, naturally senin yüklenmeni. Expose nominalization instead of a context-only copy of a converb.")
    c("5:29", "coordinated-result", {2: "isterim", 7: "böylece olmanı"}, "After the nominal content yüklenmeni under isterim, the result fa-takuna remains part of that desired content as böylece olmanı; do not leave an unattached olasın beside the nominal complement.")
    d("5:29:3", "Restore the nominal desired-content complement while retaining the result clause's first-person wish context.")
    d("5:31:5 5:33:19", "Retain the inspected idioms: Turkish yeri eşelemek absorbs fi into a direct-object frame, and min khilaf is the crosswise manner çapraz. A literal yerden or karşıtlıktan would change those Turkish constructions.", True)
    d("5:41:29 5:41:30 5:41:31", "Retain the explicit interpretive paraphrase yerlerine konulduktan sonra for min badi mawadiihi: words are distorted after being set in their proper places. The temporal and nominal contributions are separately exposed; this decision does not pretend mawadi lexically contains a passive verb.", True)
    d("5:46:11 5:46:22 5:48:9", "Min identifies the scripture being confirmed; retain the direct object Tevrat'ı / Kitabı without a forced ablative. This decision concerns min only; the idiomatic temporal meaning of bayna yadayhi is separately noted for follow-up.", True)
    p("5:48", "away-from-truth", [("sana gel", 22), ("en", 21), (" ", 0), ("gerçek", 24), ("ten [ayrılıp]", 21)], "Amma is an plus relative ma: away from what came to you. Move the relative ending and departure relation to amma, not the explanatory min before al-haqq; min identifies that content as truth.")
    c("5:48", "explanatory-truth", {23: "(gerçek)"}, "The min before al-haqq is explanatory identification of the truth, not the source of the separate departing-from relation supplied by amma.")
    d("5:48:21 5:48:23", "Separate amma's departure/relative role from explanatory min. Retain the explicit contextual ayrılıp as bracketed support rather than calling it a literal Arabic verb.")
    p("5:48", "given-things", [("size ver", 40), ("dik", 39), ("leri", 40)], "Ma at fi ma atakum supplies what was given: size verdikleri, an inflected nominal-relative object of the Turkish testing frame ile. It does not mean the preposition ile itself.")
    d("5:48:39", "Restore the nominal-relative contribution at ma and leave the testing instrument frame at fi.")
    d("5:52:15", "Under asa, an introduces the content of the possible bringing. Turkish belki Allah getirir naturally realizes that modal complement without an extra noun suffix. Retain the context-only view rather than duplicating belki or inserting a false tense.", True)
    b.finish(args.apply)


if __name__ == "__main__":
    main()
